-- ── AFRIQUE DU SUD ──
INSERT INTO `producer_countries` (`id`, `name`, `flag`, `lat`, `lon`, `color`, `tier`, `region`, `region_en`, `region_es`, `region_de`, `region_zh`, `region_ar`, `regions`, `varieties`, `tabacaleras`, `brands`, `production`, `production_en`, `production_es`, `production_de`, `production_zh`, `production_ar`, `revenue`, `rev_detail`, `rev_detail_en`, `rev_detail_es`, `rev_detail_de`, `rev_detail_zh`, `rev_detail_ar`, `notes`, `notes_en`, `notes_es`, `notes_de`, `notes_zh`, `notes_ar`)
VALUES ('southafrica',
  'Afrique du Sud',
  CONVERT(UNHEX('F09F87BFF09F87A6') USING utf8mb4),
  -28.4793,
  24.6727,
  '#2A7F62',
  'emerging',
  'Afrique australe',
  'Southern Africa',
  'África Austral',
  'Südliches Afrika',
  '南部非洲',
  'الجنوب الأفريقي',
  '[]',
  '[]',
  '["Santa Bras Cigars (George)"]',
  '[{"name":"Santa Bras","desc":"George, années 1990 — un passe-temps devenu le seul atelier du pays, dit-il","iconic":true}]',
  'Un atelier qui roule à la main à George (Western Cape) — non chiffré',
  'One workshop rolling by hand in George (Western Cape) — unquantified',
  'Un taller que lía a mano en George (Western Cape) — sin cifra',
  'Eine Werkstatt, die in George (Western Cape) von Hand rollt — unbeziffert',
  '乔治（西开普省）一家手工卷制作坊——无数字',
  'ورشة واحدة تلفّ يدويًّا في جورج (الكيب الغربية) — بلا رقم',
  '',
  'Aucun chiffre. L''Afrique du Sud cultive du tabac — trois à quatre cents planteurs, dont un cinquième environ en séchage à l''air, dit la presse agricole de 2023 — et n''a qu''un atelier qui en fasse des cigares. La cape et la sous-cape viendraient d''une vallée du Western Cape, la tripe de l''Eastern Cape : c''est la maison qui le dit.',
  'No figures. South Africa grows tobacco — three to four hundred growers, about a fifth of them air-curing, says the farming press of 2023 — and has only one workshop making cigars from it. Wrapper and binder would come from a Western Cape valley, filler from the Eastern Cape: that is the house speaking.',
  'Ninguna cifra. Sudáfrica cultiva tabaco — de trescientos a cuatrocientos plantadores, cerca de un quinto en curado al aire, dice la prensa agrícola de 2023 — y solo tiene un taller que haga puros con él. Capa y capote vendrían de un valle del Western Cape, la tripa del Eastern Cape: lo dice la casa.',
  'Keine Zahlen. Südafrika baut Tabak an — drei- bis vierhundert Pflanzer, etwa ein Fünftel davon luftgetrocknet, sagt die Agrarpresse von 2023 — und hat nur eine Werkstatt, die daraus Zigarren macht. Deckblatt und Umblatt kämen aus einem Tal des Western Cape, die Einlage aus dem Eastern Cape: das sagt das Haus.',
  '没有数字。南非种植烟草——2023年农业媒体称有三四百家种植者，约五分之一为晾制——只有一家作坊用它做雪茄。茄衣和茄套据说来自西开普省的一处山谷，茄芯来自东开普省：这是公司的说法。',
  'لا أرقام. تزرع جنوب أفريقيا التبغ — ثلاثمئة إلى أربعمئة مزارع، نحو خُمسهم بالتجفيف الهوائي، تقول الصحافة الزراعية سنة 2023 — وليس فيها سوى ورشة واحدة تصنع منه السيجار. الغلاف والرابط يأتيان، كما تقول الدار، من وادٍ في الكيب الغربية، والحشوة من الكيب الشرقية.',
  'Un pays qui fume beaucoup de cigares importés — Le Cap, Johannesburg ont leurs salons — et qui n''en roule presque pas. L''atlas y porte une seule maison, Santa Bras, née d''un passe-temps des années 1990 dans la région de George, qui se dit le seul fabricant du pays. Sa vallée de tabac, entre le Swartberg et les Outeniqua, n''est décrite que par elle : l''atlas la note sans la porter comme zone.',
  'A country that smokes many imported cigars — Cape Town and Johannesburg have their lounges — and rolls almost none. This atlas carries a single house there, Santa Bras, born of a 1990s hobby around George, which calls itself the country''s only manufacturer. Its tobacco valley, between the Swartberg and the Outeniqua, is described only by the house: the atlas notes it without carrying it as a zone.',
  'Un país que fuma muchos puros importados — Ciudad del Cabo, Johannesburgo tienen sus salones — y que casi no lía. Este atlas recoge allí una sola casa, Santa Bras, nacida de una afición de los años noventa en la región de George, que se dice el único fabricante del país. Su valle de tabaco, entre el Swartberg y los Outeniqua, solo lo describe ella: el atlas lo anota sin recogerlo como zona.',
  'Ein Land, das viele importierte Zigarren raucht — Kapstadt und Johannesburg haben ihre Lounges — und fast keine rollt. Dieser Atlas führt dort ein einziges Haus, Santa Bras, aus einem Hobby der 1990er Jahre in der Gegend von George entstanden, das sich den einzigen Hersteller des Landes nennt. Sein Tabaktal zwischen Swartberg und Outeniqua beschreibt nur das Haus selbst: Der Atlas vermerkt es, ohne es als Zone zu führen.',
  '这个国家抽很多进口雪茄——开普敦、约翰内斯堡都有雪茄吧——却几乎不卷。本图集在此只收录一家：Santa Bras，源于1990年代乔治地区的一项爱好，自称全国仅有的制造商。它的烟草山谷位于斯瓦特山与奥特尼夸山之间，只有公司自己描述过：图集记下，但不列为产区。',
  'بلد يدخّن كثيرًا من السيجار المستورد — لكيب تاون وجوهانسبرغ صالوناتهما — ولا يكاد يلفّ. يحمل هذا الأطلس فيه دارًا واحدة، Santa Bras، وُلدت من هواية في التسعينيات في منطقة جورج، وتقول عن نفسها إنّها الصانع الوحيد في البلاد. أمّا واديها للتبغ، بين سوارتبرغ وأوتنيكوا، فلا تصفه سواها: يدوّنه الأطلس من دون أن يحمله منطقةً.')
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `flag` = VALUES(`flag`), `lat` = VALUES(`lat`), `lon` = VALUES(`lon`), `color` = VALUES(`color`), `tier` = VALUES(`tier`), `region` = VALUES(`region`), `region_en` = VALUES(`region_en`), `region_es` = VALUES(`region_es`), `region_de` = VALUES(`region_de`), `region_zh` = VALUES(`region_zh`), `region_ar` = VALUES(`region_ar`), `regions` = VALUES(`regions`), `varieties` = VALUES(`varieties`), `tabacaleras` = VALUES(`tabacaleras`), `brands` = VALUES(`brands`), `production` = VALUES(`production`), `production_en` = VALUES(`production_en`), `production_es` = VALUES(`production_es`), `production_de` = VALUES(`production_de`), `production_zh` = VALUES(`production_zh`), `production_ar` = VALUES(`production_ar`), `revenue` = VALUES(`revenue`), `rev_detail` = VALUES(`rev_detail`), `rev_detail_en` = VALUES(`rev_detail_en`), `rev_detail_es` = VALUES(`rev_detail_es`), `rev_detail_de` = VALUES(`rev_detail_de`), `rev_detail_zh` = VALUES(`rev_detail_zh`), `rev_detail_ar` = VALUES(`rev_detail_ar`), `notes` = VALUES(`notes`), `notes_en` = VALUES(`notes_en`), `notes_es` = VALUES(`notes_es`), `notes_de` = VALUES(`notes_de`), `notes_zh` = VALUES(`notes_zh`), `notes_ar` = VALUES(`notes_ar`);

