INSERT INTO `producer_countries` (`id`, `name`, `flag`, `lat`, `lon`, `color`, `tier`, `region`, `region_en`, `region_es`, `region_de`, `region_zh`, `region_ar`, `regions`, `varieties`, `tabacaleras`, `brands`, `production`, `production_en`, `production_es`, `production_de`, `production_zh`, `production_ar`, `revenue`, `rev_detail`, `rev_detail_en`, `rev_detail_es`, `rev_detail_de`, `rev_detail_zh`, `rev_detail_ar`, `notes`, `notes_en`, `notes_es`, `notes_de`, `notes_zh`, `notes_ar`)
VALUES ('peru',
  'Pérou',
  CONVERT(UNHEX('F09F87B5F09F87AA') USING utf8mb4),
  -9.19,
  -75.0152,
  '#C0392B',
  'emerging',
  'Amérique du Sud',
  'South America',
  'América del Sur',
  'Südamerika',
  '南美洲',
  'أمريكا الجنوبية',
  '["Juan Guerra (San Martín)"]',
  '[]',
  '["Tabacalera del Oriente (Tarapoto)"]',
  '[{"name":"Tabacalera del Oriente","desc":"Tarapoto — la famille Lettieri, des champs à Juan Guerra, cent pour cent péruvien","iconic":true}]',
  'Environ 500 000 cigares par an à Tarapoto (2016) ; un million selon la presse de 2023',
  'About 500,000 cigars a year in Tarapoto (2016); one million according to the 2023 press',
  'Unos 500 000 puros al año en Tarapoto (2016); un millón según la prensa de 2023',
  'Etwa 500 000 Zigarren im Jahr in Tarapoto (2016); eine Million laut der Presse von 2023',
  '塔拉波托每年约50万支（2016年）；据2023年媒体为一百万支',
  'نحو 500 ألف سيجار في السنة في تارابوتو (2016)؛ ومليون بحسب صحافة 2023',
  '',
  'Le tabac de Tarapoto se vend d''abord en feuilles : 80 à 100 tonnes exportées par an vers l''Amérique centrale (2016), 70 % du chiffre contre 30 % pour le cigare fini — la maison veut inverser la proportion. Les cigares partent à 80 % à l''export, en Europe et en Asie ; un contrat italien de 2011 valait 220 000 dollars.',
  'Tarapoto tobacco sells first as leaf: 80 to 100 tonnes exported a year to Central America (2016), 70% of turnover against 30% for finished cigars — the house wants to reverse the proportion. The cigars go 80% to export, in Europe and Asia; an Italian contract of 2011 was worth 220,000 dollars.',
  'El tabaco de Tarapoto se vende primero en hoja: de 80 a 100 toneladas exportadas al año hacia Centroamérica (2016), 70 % de la cifra frente a 30 % para el puro terminado — la casa quiere invertir la proporción. Los puros salen en un 80 % a la exportación, a Europa y Asia; un contrato italiano de 2011 valía 220 000 dólares.',
  'Der Tabak von Tarapoto verkauft sich zuerst als Blatt: 80 bis 100 Tonnen im Jahr nach Mittelamerika exportiert (2016), 70 % des Umsatzes gegen 30 % für die fertige Zigarre — das Haus will das Verhältnis umkehren. Die Zigarren gehen zu 80 % in den Export, nach Europa und Asien; ein italienischer Vertrag von 2011 war 220 000 Dollar wert.',
  '塔拉波托的烟叶首先以原叶出售：每年向中美洲出口80到100吨（2016年），占营业额70%，成品雪茄占30%——公司想把比例倒过来。雪茄八成出口，销往欧洲和亚洲；2011年一份意大利合同价值22万美元。',
  'يُباع تبغ تارابوتو أوّلًا ورقًا: 80 إلى 100 طن تُصدَّر سنويًّا إلى أمريكا الوسطى (2016)، 70 % من الرقم مقابل 30 % للسيجار الجاهز — وتريد الدار قلب النسبة. ويذهب 80 % من السيجار إلى التصدير، في أوروبا وآسيا؛ وبلغ عقد إيطالي سنة 2011 قيمة 220 ألف دولار.',
  'Le Pérou est un pays de tabac ancien — des chercheurs cubains ont placé l''origine de la plante dans sa ceja de selva, près de Cusco — et un pays de cigare récent, tenu par une seule fabrique à Tarapoto, dans le département de San Martín. Elle cultive à Juan Guerra, à quinze kilomètres de la ville, et peut planter toute l''année, ce que les Caraïbes ne peuvent pas. L''atlas porte la zone ; les trois variétés que la presse agricole a nommées — Negro, Pelo de Oro, Criollo — n''ont pas de fiche et restent ici.',
  'Peru is an old tobacco country — Cuban researchers placed the plant''s origin in its ceja de selva, near Cusco — and a recent cigar country, held by a single factory in Tarapoto, in the department of San Martín. It grows at Juan Guerra, fifteen kilometres from the town, and can plant all year round, which the Caribbean cannot. This atlas carries the zone; the three varieties the farming press has named — Negro, Pelo de Oro, Criollo — have no entry and stay here.',
  'Perú es un país de tabaco antiguo — investigadores cubanos situaron el origen de la planta en su ceja de selva, cerca de Cusco — y un país de puro reciente, sostenido por una sola fábrica en Tarapoto, en el departamento de San Martín. Cultiva en Juan Guerra, a quince kilómetros de la ciudad, y puede sembrar todo el año, lo que el Caribe no puede. Este atlas recoge la zona; las tres variedades que la prensa agrícola ha nombrado — Negro, Pelo de Oro, Criollo — no tienen ficha y se quedan aquí.',
  'Peru ist ein altes Tabakland — kubanische Forscher verorteten den Ursprung der Pflanze in seiner ceja de selva bei Cusco — und ein junges Zigarrenland, getragen von einer einzigen Fabrik in Tarapoto im Departement San Martín. Sie baut in Juan Guerra an, fünfzehn Kilometer von der Stadt, und kann das ganze Jahr pflanzen, was die Karibik nicht kann. Dieser Atlas führt die Zone; die drei Sorten, die die Agrarpresse genannt hat — Negro, Pelo de Oro, Criollo —, haben keinen Eintrag und bleiben hier.',
  '秘鲁是一个古老的烟草之国——古巴研究者把这种植物的起源定在库斯科附近的林缘地带——也是一个年轻的雪茄之国，由圣马丁大区塔拉波托的一家工厂撑起。它在离城十五公里的胡安格拉种植，可以全年播种，这是加勒比做不到的。本图集收录该产区；农业媒体点名的三个品种——Negro、Pelo de Oro、Criollo——没有词条，留在此处。',
  'بيرو بلد تبغ قديم — وضع باحثون كوبيون أصل النبتة في حافة غابتها قرب كوسكو — وبلد سيجار حديث، يقوم على مصنع واحد في تارابوتو بمقاطعة سان مارتين. يزرع في خوان غيرا، على خمسة عشر كيلومترًا من المدينة، ويستطيع الزراعة على مدار السنة، وهو ما لا يستطيعه الكاريبي. يحمل هذا الأطلس المنطقة؛ أمّا الأصناف الثلاثة التي سمّتها الصحافة الزراعية — Negro وPelo de Oro وCriollo — فلا بطاقة لها وتبقى هنا.')
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `flag` = VALUES(`flag`), `lat` = VALUES(`lat`), `lon` = VALUES(`lon`), `color` = VALUES(`color`), `tier` = VALUES(`tier`), `region` = VALUES(`region`), `region_en` = VALUES(`region_en`), `region_es` = VALUES(`region_es`), `region_de` = VALUES(`region_de`), `region_zh` = VALUES(`region_zh`), `region_ar` = VALUES(`region_ar`), `regions` = VALUES(`regions`), `varieties` = VALUES(`varieties`), `tabacaleras` = VALUES(`tabacaleras`), `brands` = VALUES(`brands`), `production` = VALUES(`production`), `production_en` = VALUES(`production_en`), `production_es` = VALUES(`production_es`), `production_de` = VALUES(`production_de`), `production_zh` = VALUES(`production_zh`), `production_ar` = VALUES(`production_ar`), `revenue` = VALUES(`revenue`), `rev_detail` = VALUES(`rev_detail`), `rev_detail_en` = VALUES(`rev_detail_en`), `rev_detail_es` = VALUES(`rev_detail_es`), `rev_detail_de` = VALUES(`rev_detail_de`), `rev_detail_zh` = VALUES(`rev_detail_zh`), `rev_detail_ar` = VALUES(`rev_detail_ar`), `notes` = VALUES(`notes`), `notes_en` = VALUES(`notes_en`), `notes_es` = VALUES(`notes_es`), `notes_de` = VALUES(`notes_de`), `notes_zh` = VALUES(`notes_zh`), `notes_ar` = VALUES(`notes_ar`);

