-- ── COLOMBIE ──
INSERT INTO `producer_countries` (`id`, `name`, `flag`, `lat`, `lon`, `color`, `tier`, `region`, `region_en`, `region_es`, `region_de`, `region_zh`, `region_ar`, `regions`, `varieties`, `tabacaleras`, `brands`, `production`, `production_en`, `production_es`, `production_de`, `production_zh`, `production_ar`, `revenue`, `rev_detail`, `rev_detail_en`, `rev_detail_es`, `rev_detail_de`, `rev_detail_zh`, `rev_detail_ar`, `notes`, `notes_en`, `notes_es`, `notes_de`, `notes_zh`, `notes_ar`)
VALUES ('colombia',
  'Colombie',
  CONVERT(UNHEX('F09F87A8F09F87B4') USING utf8mb4),
  4.5709,
  -74.2973,
  '#D4A017',
  'emerging',
  'Amérique du Sud',
  'South America',
  'América del Sur',
  'Südamerika',
  '南美洲',
  'أمريكا الجنوبية',
  '["Piedecuesta (Santander)"]',
  '[]',
  '["Casa del Tabaco Corona Real (Piedecuesta)","Colpuros (Piedecuesta)"]',
  '[{"name":"Corona Real","desc":"Piedecuesta, 2006 — Gabriel Pico, dans le tabac depuis ses douze ans","iconic":true},{"name":"Colpuros","desc":"Piedecuesta, 2009 — la famille Correa, de Zapatoca ; des puros en Allemagne","iconic":false}]',
  'Piedecuesta (Santander) roule à la main, surtout du tabaco populaire ; deux maisons de puros portées ici',
  'Piedecuesta (Santander) rolls by hand, mostly popular tabaco; two puro houses carried here',
  'Piedecuesta (Santander) lía a mano, sobre todo tabaco popular; dos casas de puros recogidas aquí',
  'Piedecuesta (Santander) rollt von Hand, vor allem den einfachen tabaco; zwei Puro-Häuser hier geführt',
  '皮耶德奎斯塔（桑坦德省）手工卷制，主要是大众的 tabaco；此处收录两家 puro 之家',
  'تلفّ بييديكويستا (سانتاندير) يدويًّا، وأكثره التبغ الشعبي؛ داران للسيجار الفاخر تُحملان هنا',
  '',
  'Le tabac fait 40 % du produit municipal de Piedecuesta et fait vivre 4 500 à 6 500 familles, selon l''année et le journal ; deux cents fabricants, 78 % de femmes (2018). Presque tout est du tabaco bon marché ; le puro premium est l''affaire de quelques maisons, et l''export reste rare — Colpuros a placé des puros en Allemagne en 2018 après quatre ans sans aucun envoi du secteur.',
  'Tobacco makes 40% of Piedecuesta''s municipal product and feeds 4,500 to 6,500 families, depending on the year and the newspaper; two hundred makers, 78% women (2018). Almost all of it is cheap tabaco; the premium puro is the business of a few houses, and export remains rare — Colpuros placed puros in Germany in 2018 after four years without any shipment from the sector.',
  'El tabaco hace el 40 % del producto municipal de Piedecuesta y sostiene de 4 500 a 6 500 familias, según el año y el diario; doscientos fabricantes, 78 % mujeres (2018). Casi todo es tabaco barato; el puro premium es asunto de unas pocas casas, y la exportación sigue siendo rara — Colpuros colocó puros en Alemania en 2018 tras cuatro años sin ningún envío del sector.',
  'Tabak macht 40 % des Gemeindeprodukts von Piedecuesta aus und ernährt 4 500 bis 6 500 Familien, je nach Jahr und Zeitung; zweihundert Hersteller, 78 % Frauen (2018). Fast alles ist billiger tabaco; der Premium-Puro ist Sache weniger Häuser, und der Export bleibt selten — Colpuros brachte 2018 Puros nach Deutschland, nach vier Jahren ohne eine Lieferung des Sektors.',
  '烟草占皮耶德奎斯塔市产值的40%，养活4500到6500个家庭（因年份和报纸而异）；两百家制造者，78%为女性（2018年）。几乎全是廉价 tabaco；高档 puro 只是少数几家的事，出口仍然稀少——Colpuros 于2018年把 puro 送进德国，此前该行业四年没有任何出货。',
  'يشكّل التبغ 40 % من ناتج بلدية بييديكويستا ويعيل 4500 إلى 6500 أسرة بحسب السنة والصحيفة؛ مئتا صانع، 78 % منهم نساء (2018). يكاد كلّه تبغًا رخيصًا؛ والسيجار الفاخر شأن دور قليلة، ويبقى التصدير نادرًا — وضعت Colpuros سيجارًا في ألمانيا سنة 2018 بعد أربع سنوات من دون أيّ شحنة من القطاع.',
  'Piedecuesta, près de Bucaramanga, roule du tabac depuis sa fondation et concentre, dit un fabricant, 95 % de ce qui se fait en Colombie — mais c''est du tabaco, le cigare populaire du Santander, pas du puro. Le puro y est une greffe récente : deux maisons, l''une née d''un garçon qui liait des feuilles à douze ans, l''autre d''une famille de tabaqueros de Zapatoca, toutes deux formées auprès de Cubains. L''atlas porte Piedecuesta comme zone ; les trois variétés que la presse a nommées — Costeña, Guane, Cubita — n''ont pas de fiche et restent ici.',
  'Piedecuesta, near Bucaramanga, has rolled tobacco since its founding and concentrates, says one maker, 95% of what is made in Colombia — but that is tabaco, Santander''s popular cigar, not puro. The puro there is a recent graft: two houses, one born of a boy who tied leaves at twelve, the other of a family of tabaqueros from Zapatoca, both trained by Cubans. This atlas carries Piedecuesta as a zone; the three varieties the press has named — Costeña, Guane, Cubita — have no entry and stay here.',
  'Piedecuesta, cerca de Bucaramanga, lía tabaco desde su fundación y concentra, dice un fabricante, el 95 % de lo que se hace en Colombia — pero eso es tabaco, el cigarro popular de Santander, no puro. El puro es allí un injerto reciente: dos casas, una nacida de un muchacho que ataba hojas a los doce años, la otra de una familia de tabaqueros de Zapatoca, ambas formadas con cubanos. Este atlas recoge Piedecuesta como zona; las tres variedades que la prensa ha nombrado — Costeña, Guane, Cubita — no tienen ficha y se quedan aquí.',
  'Piedecuesta bei Bucaramanga rollt Tabak seit seiner Gründung und vereint, sagt ein Hersteller, 95 % dessen, was in Kolumbien gemacht wird — doch das ist tabaco, die Volkszigarre Santanders, kein Puro. Der Puro ist dort eine junge Veredelung: zwei Häuser, eines aus einem Jungen hervorgegangen, der mit zwölf Blätter band, das andere aus einer Familie von tabaqueros aus Zapatoca, beide von Kubanern ausgebildet. Dieser Atlas führt Piedecuesta als Zone; die drei Sorten, die die Presse genannt hat — Costeña, Guane, Cubita —, haben keinen Eintrag und bleiben hier.',
  '布卡拉曼加附近的皮耶德奎斯塔自建镇起就卷烟草，一位制造者说，哥伦比亚95%的产量集中于此——但那是 tabaco，桑坦德的大众雪茄，不是 puro。puro 在这里是新近的嫁接：两家，一家出自一个十二岁就捆烟叶的男孩，另一家出自萨帕托卡的烟草世家，都受过古巴人的训练。本图集把皮耶德奎斯塔列为产区；媒体点名的三个品种——Costeña、Guane、Cubita——没有词条，留在此处。',
  'تلفّ بييديكويستا، قرب بوكارامانغا، التبغ منذ تأسيسها وتجمع، كما يقول أحد الصنّاع، 95 % ممّا يُصنع في كولومبيا — لكنّه التبغ الشعبي، سيجار سانتاندير العامّ، لا السيجار الفاخر. والسيجار الفاخر هناك طُعمٌ حديث: داران، إحداهما وُلدت من صبيّ كان يربط الأوراق في الثانية عشرة، والأخرى من عائلة تبغيّين من زاباتوكا، وكلتاهما تدرّبت على يد كوبيين. يحمل هذا الأطلس بييديكويستا منطقةً؛ أمّا الأصناف الثلاثة التي سمّتها الصحافة — Costeña وGuane وCubita — فلا بطاقة لها وتبقى هنا.')
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `flag` = VALUES(`flag`), `lat` = VALUES(`lat`), `lon` = VALUES(`lon`), `color` = VALUES(`color`), `tier` = VALUES(`tier`), `region` = VALUES(`region`), `region_en` = VALUES(`region_en`), `region_es` = VALUES(`region_es`), `region_de` = VALUES(`region_de`), `region_zh` = VALUES(`region_zh`), `region_ar` = VALUES(`region_ar`), `regions` = VALUES(`regions`), `varieties` = VALUES(`varieties`), `tabacaleras` = VALUES(`tabacaleras`), `brands` = VALUES(`brands`), `production` = VALUES(`production`), `production_en` = VALUES(`production_en`), `production_es` = VALUES(`production_es`), `production_de` = VALUES(`production_de`), `production_zh` = VALUES(`production_zh`), `production_ar` = VALUES(`production_ar`), `revenue` = VALUES(`revenue`), `rev_detail` = VALUES(`rev_detail`), `rev_detail_en` = VALUES(`rev_detail_en`), `rev_detail_es` = VALUES(`rev_detail_es`), `rev_detail_de` = VALUES(`rev_detail_de`), `rev_detail_zh` = VALUES(`rev_detail_zh`), `rev_detail_ar` = VALUES(`rev_detail_ar`), `notes` = VALUES(`notes`), `notes_en` = VALUES(`notes_en`), `notes_es` = VALUES(`notes_es`), `notes_de` = VALUES(`notes_de`), `notes_zh` = VALUES(`notes_zh`), `notes_ar` = VALUES(`notes_ar`);

