-- ── ARUBA ──
INSERT INTO `producer_countries` (`id`, `name`, `flag`, `lat`, `lon`, `color`, `tier`, `region`, `region_en`, `region_es`, `region_de`, `region_zh`, `region_ar`, `regions`, `varieties`, `tabacaleras`, `brands`, `production`, `production_en`, `production_es`, `production_de`, `production_zh`, `production_ar`, `revenue`, `rev_detail`, `rev_detail_en`, `rev_detail_es`, `rev_detail_de`, `rev_detail_zh`, `rev_detail_ar`, `notes`, `notes_en`, `notes_es`, `notes_de`, `notes_zh`, `notes_ar`)
VALUES ('aruba',
  'Aruba',
  CONVERT(UNHEX('F09F87A6F09F87BC') USING utf8mb4),
  12.5211,
  -69.9683,
  '#3C8DBC',
  'emerging',
  'Caraïbes',
  'Caribbean',
  'Caribe',
  'Karibik',
  '加勒比地区',
  'الكاريبي',
  '[]',
  '[]',
  '["Aruhiba (Noord)"]',
  '[{"name":"Aruhiba","desc":"Noord, 2005 — Benjamin Petrocchi cultive, sèche et roule sur l''île","iconic":true}]',
  'Un atelier à Noord — environ quarante cigares par heure, dit un guide néerlandais',
  'One workshop in Noord — about forty cigars an hour, says a Dutch guide',
  'Un taller en Noord — unos cuarenta puros por hora, dice una guía neerlandesa',
  'Eine Werkstatt in Noord — etwa vierzig Zigarren in der Stunde, sagt ein niederländischer Führer',
  '诺德一家作坊——荷兰旅游指南称每小时约四十支',
  'ورشة واحدة في نورد — نحو أربعين سيجارًا في الساعة، يقول دليل هولندي',
  '',
  'Aucun chiffre. Aruba est une île de tourisme — cent mille habitants, des hôtels sur Palm Beach — et le cigare y est une boutique près du moulin hollandais, qui vend aux visiteurs ce qu''elle roule l''après-midi. Le tabac pousse sur l''île, sur une terre qui donnait des haricots.',
  'No figures. Aruba is a tourism island — a hundred thousand inhabitants, hotels along Palm Beach — and the cigar there is a shop near the Dutch windmill, selling visitors what it rolls in the afternoon. The tobacco grows on the island, on land that used to give beans.',
  'Ninguna cifra. Aruba es una isla de turismo — cien mil habitantes, hoteles en Palm Beach — y el puro es allí una tienda junto al molino holandés, que vende a los visitantes lo que lía por la tarde. El tabaco crece en la isla, en una tierra que daba frijoles.',
  'Keine Zahlen. Aruba ist eine Tourismusinsel — hunderttausend Einwohner, Hotels an Palm Beach —, und die Zigarre ist dort ein Laden bei der holländischen Windmühle, der Besuchern verkauft, was er nachmittags rollt. Der Tabak wächst auf der Insel, auf Land, das einst Bohnen trug.',
  '没有数字。阿鲁巴是旅游之岛——十万居民，棕榈滩沿岸的酒店——雪茄在这里是荷兰风车旁的一家店，下午卷，卖给游客。烟草就在岛上种植，那片地过去种豆子。',
  'لا أرقام. أروبا جزيرة سياحة — مئة ألف نسمة، وفنادق على بالم بيتش — والسيجار فيها متجر قرب الطاحونة الهولندية يبيع للزوّار ما يلفّه بعد الظهر. ينمو التبغ في الجزيرة، على أرض كانت تعطي الفاصولياء.',
  'Une île aride, du cactus et du vent, où un fils de cultivateurs de haricots a planté du tabac et s''est mis à le rouler vers 2005. Aucune presse du cigare ne l''a écrit ; l''atlas tient l''histoire d''un office de tourisme, d''un guide néerlandais et d''un annuaire de voyage, et le dit. L''ancien domaine de la maison sert aujourd''hui une boutique en Ukraine sans rapport avec elle — l''atlas ne le cite pas.',
  'An arid island, cactus and wind, where a bean farmers'' son planted tobacco and began rolling it around 2005. No cigar press has written it; this atlas holds the story from a tourism office, a Dutch guide and a travel directory, and says so. The house''s former domain now serves a shop in Ukraine unrelated to it — the atlas does not cite it.',
  'Una isla árida, cactus y viento, donde un hijo de cultivadores de frijol plantó tabaco y se puso a liarlo hacia 2005. Ninguna prensa del puro lo ha escrito; este atlas tiene la historia de una oficina de turismo, de una guía neerlandesa y de un directorio de viajes, y lo dice. El antiguo dominio de la casa sirve hoy a una tienda en Ucrania sin relación con ella — el atlas no lo cita.',
  'Eine karge Insel, Kakteen und Wind, auf der ein Sohn von Bohnenbauern Tabak pflanzte und ihn um 2005 zu rollen begann. Keine Zigarrenpresse hat es geschrieben; dieser Atlas hat die Geschichte von einem Fremdenverkehrsamt, einem niederländischen Führer und einem Reiseverzeichnis, und sagt es. Die frühere Domain des Hauses bedient heute einen Laden in der Ukraine ohne Bezug zu ihm — der Atlas zitiert sie nicht.',
  '一座干旱的岛，仙人掌和风，一位豆农之子在此种下烟草，并于2005年前后开始卷制。没有雪茄媒体写过它；本图集的故事来自旅游局、荷兰指南和旅行名录，并如实说明。公司过去的域名如今是一家与它无关的乌克兰店铺——图集不引用它。',
  'جزيرة قاحلة، صبّار وريح، غرس فيها ابن مزارعي فاصولياء التبغ وشرع يلفّه نحو 2005. لم تكتبه أيّ صحافة سيجار؛ يأخذ هذا الأطلس الحكاية من مكتب سياحة ودليل هولندي ودليل سفر، ويقول ذلك. أمّا نطاق الدار القديم فيخدم اليوم متجرًا في أوكرانيا لا صلة له بها — ولا يستشهد به الأطلس.')
ON DUPLICATE KEY UPDATE `name` = VALUES(`name`), `flag` = VALUES(`flag`), `lat` = VALUES(`lat`), `lon` = VALUES(`lon`), `color` = VALUES(`color`), `tier` = VALUES(`tier`), `region` = VALUES(`region`), `region_en` = VALUES(`region_en`), `region_es` = VALUES(`region_es`), `region_de` = VALUES(`region_de`), `region_zh` = VALUES(`region_zh`), `region_ar` = VALUES(`region_ar`), `regions` = VALUES(`regions`), `varieties` = VALUES(`varieties`), `tabacaleras` = VALUES(`tabacaleras`), `brands` = VALUES(`brands`), `production` = VALUES(`production`), `production_en` = VALUES(`production_en`), `production_es` = VALUES(`production_es`), `production_de` = VALUES(`production_de`), `production_zh` = VALUES(`production_zh`), `production_ar` = VALUES(`production_ar`), `revenue` = VALUES(`revenue`), `rev_detail` = VALUES(`rev_detail`), `rev_detail_en` = VALUES(`rev_detail_en`), `rev_detail_es` = VALUES(`rev_detail_es`), `rev_detail_de` = VALUES(`rev_detail_de`), `rev_detail_zh` = VALUES(`rev_detail_zh`), `rev_detail_ar` = VALUES(`rev_detail_ar`), `notes` = VALUES(`notes`), `notes_en` = VALUES(`notes_en`), `notes_es` = VALUES(`notes_es`), `notes_de` = VALUES(`notes_de`), `notes_zh` = VALUES(`notes_zh`), `notes_ar` = VALUES(`notes_ar`);

