-- ── Corona Real ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Corona Real',
        'colombia',
        '2000 (Cigarros Chicamocha) ; 2006 — Gabriel Pico',
        'Casa del Tabaco Corona Real, Piedecuesta (Santander) ; environ huit personnes (2023), tout à la main',
        'semana.com « Tabaco Corona Real: una historia hecha con las manos en Santander » (2 novembre 2021 : Gabriel Pico Gutiérrez, 53 ans ; dans le tabac depuis ses douze ans avec son père ; Cigarros Chicamocha en 2000, Corona Real en 2006 ; études d''administration interrompues ; formé à Cuba ; variétés Costeña, Guane, Cubita ; capes Sumatra d''Équateur de 2005-2006 ; export tenté et refusé) ; vanguardia.com « Gabriel Pico, un tabacalero de corazón » (7 mai 2023 : 55 ans, 43 ans de tabac ; diplômé de la UIS ; environ huit personnes ; tout à la main ; 90 % de tabac colombien — Girón, Cepitá, Jordán, Mesa de los Santos, Capitanejo, Cúcuta, Ábrego, Montes de María ; Piedecuesta ferait 95 % du tabac colombien, dit-il) ; santander.gov.co (le tabac, produit phare de Piedecuesta depuis deux siècles) — sources en espagnol, presse colombienne',
        'Corona Real est la maison de Gabriel Pico Gutiérrez à Piedecuesta, la ville du tabac du Santander, au sud de Bucaramanga. Il y est entré à douze ans, en attachant des feuilles et en livrant du tabac avec son père, puis en travaillant dans une petite fabrique à la sous-cape et à l''emballage ; il a fait des études d''administration à l''université industrielle de Santander — interrompues au septième semestre selon un journal, achevées selon l''autre ; la fiche écrit les deux — et il est allé à Cuba apprendre à faire le tabac autrement. Sa marque s''est d''abord appelée Cigarros Chicamocha, en 2000, du nom du canyon voisin, et Corona Real en 2006.

Piedecuesta roule depuis sa fondation, et 95 % du tabac colombien s''y ferait, dit-il — mais c''est du tabaco, le cigare populaire qui fait vivre des milliers de familles à quelques centaines de pesos la pièce. Corona Real fait autre chose : du puro, tout à la main, avec huit personnes environ, sur un tabac à 90 % colombien qui vient de Girón, de Cepitá, de la Mesa de los Santos, de Capitanejo, de Cúcuta, des Montes de María, et sur des capes Sumatra d''Équateur de 2005-2006 qu''il garde en vieillissement. Trois variétés locales, Costeña, Guane, Cubita.

Il vend dans toute la Colombie et n''a pas réussi à exporter — les fois qu''il a essayé, les restrictions l''ont arrêté, disait-il en 2021 ; que ses cigares aient atteint des célébrités est une anecdote qu''il raconte et que l''atlas ne reprend pas. Une fiche de presse colombienne, en espagnol, pour une maison que la presse du cigare n''a jamais écrite.',
        '[{"name":"Corona Real","color":"#8B6914","force":"Medium","wrapper":"Sumatra d’Équateur ou colombienne","vitolas":[],"story":"Le puro de la maison, tout à la main, sur tabac du Santander et cape Sumatra d''Équateur vieillie depuis 2005-2006."}]',
        'Corona Real is Gabriel Pico Gutiérrez''s house in Piedecuesta, the tobacco town of Santander, south of Bucaramanga. He entered it at twelve, tying leaves and delivering tobacco with his father, then working in a small factory at binder and packing; he studied business administration at the Industrial University of Santander — cut short in the seventh semester according to one paper, completed according to the other; the entry writes both — and went to Cuba to learn to make tobacco differently. His brand was first called Cigarros Chicamocha, in 2000, after the neighbouring canyon, and Corona Real in 2006.

Piedecuesta has rolled since its founding, and 95% of Colombian tobacco is made there, he says — but that is tabaco, the popular cigar that feeds thousands of families at a few hundred pesos apiece. Corona Real does something else: puro, all by hand, with about eight people, on tobacco 90% Colombian that comes from Girón, Cepitá, the Mesa de los Santos, Capitanejo, Cúcuta, the Montes de María, and on Ecuadorian Sumatra wrappers of 2005-2006 that he keeps ageing. Three local varieties, Costeña, Guane, Cubita.

He sells throughout Colombia and has not managed to export — the times he tried, restrictions stopped him, he said in 2021; that his cigars reached celebrities is an anecdote he tells and the atlas does not repeat. An entry from the Colombian press, in Spanish, for a house the cigar press has never written.',
        '[{"name":"Corona Real","color":"#8B6914","force":"Medium","wrapper":"Ecuadorian Sumatra or Colombian","vitolas":[],"story":"The house''s puro, all by hand, on Santander tobacco and Ecuadorian Sumatra wrapper aged since 2005-2006."}]',
        'Corona Real es la casa de Gabriel Pico Gutiérrez en Piedecuesta, la ciudad del tabaco de Santander, al sur de Bucaramanga. Entró en ella a los doce años, atando hojas y repartiendo tabaco con su padre, y luego trabajando en una pequeña fábrica en el capote y el empaque; estudió administración en la Universidad Industrial de Santander — interrumpida en el séptimo semestre según un diario, terminada según el otro; la ficha escribe las dos — y fue a Cuba a aprender a hacer el tabaco de otro modo. Su marca se llamó primero Cigarros Chicamocha, en 2000, por el cañón vecino, y Corona Real en 2006.

Piedecuesta lía desde su fundación, y el 95 % del tabaco colombiano se haría allí, dice él — pero eso es tabaco, el cigarro popular que sostiene a miles de familias a unos cientos de pesos la unidad. Corona Real hace otra cosa: puro, todo a mano, con unas ocho personas, sobre un tabaco 90 % colombiano que viene de Girón, Cepitá, la Mesa de los Santos, Capitanejo, Cúcuta, los Montes de María, y sobre capas Sumatra de Ecuador de 2005-2006 que guarda en añejamiento. Tres variedades locales, Costeña, Guane, Cubita.

Vende en toda Colombia y no ha logrado exportar — las veces que lo intentó, las restricciones lo frenaron, decía en 2021; que sus puros hayan llegado a celebridades es una anécdota que cuenta y que el atlas no repite. Una ficha de prensa colombiana, en español, para una casa que la prensa del puro nunca ha escrito.',
        '[{"name":"Corona Real","color":"#8B6914","force":"Medium","wrapper":"Sumatra de Ecuador o colombiana","vitolas":[],"story":"El puro de la casa, todo a mano, sobre tabaco de Santander y capa Sumatra de Ecuador añejada desde 2005-2006."}]',
        'Corona Real ist das Haus von Gabriel Pico Gutiérrez in Piedecuesta, der Tabakstadt Santanders südlich von Bucaramanga. Er trat mit zwölf ein, band Blätter und lieferte mit seinem Vater Tabak aus, arbeitete dann in einer kleinen Fabrik am Umblatt und in der Verpackung; er studierte Betriebswirtschaft an der Industrieuniversität Santander — im siebten Semester abgebrochen laut der einen Zeitung, abgeschlossen laut der anderen; der Eintrag schreibt beides — und ging nach Kuba, um Tabak anders machen zu lernen. Seine Marke hieß zuerst Cigarros Chicamocha, 2000, nach der benachbarten Schlucht, und Corona Real ab 2006.

Piedecuesta rollt seit seiner Gründung, und 95 % des kolumbianischen Tabaks würden dort gemacht, sagt er — doch das ist tabaco, die Volkszigarre, die Tausende Familien mit ein paar hundert Pesos pro Stück ernährt. Corona Real macht etwas anderes: Puro, alles von Hand, mit etwa acht Leuten, auf zu 90 % kolumbianischem Tabak aus Girón, Cepitá, der Mesa de los Santos, Capitanejo, Cúcuta, den Montes de María, und auf ecuadorianischen Sumatra-Deckblättern von 2005-2006, die er reifen lässt. Drei heimische Sorten, Costeña, Guane, Cubita.

Er verkauft in ganz Kolumbien und hat den Export nicht geschafft — wann immer er es versuchte, hielten ihn Beschränkungen auf, sagte er 2021; dass seine Zigarren Berühmtheiten erreicht hätten, ist eine Anekdote, die er erzählt und die der Atlas nicht wiederholt. Ein Eintrag aus der kolumbianischen Presse, auf Spanisch, für ein Haus, das die Zigarrenpresse nie geschrieben hat.',
        '[{"name":"Corona Real","color":"#8B6914","force":"Medium","wrapper":"Sumatra aus Ecuador oder kolumbianisch","vitolas":[],"story":"Der Puro des Hauses, ganz von Hand, auf Santander-Tabak und seit 2005-2006 gereiftem Sumatra-Deckblatt aus Ecuador."}]',
        'Corona Real 是加夫列尔·皮科·古铁雷斯在皮耶德奎斯塔的公司，那是布卡拉曼加以南桑坦德省的烟草之城。他十二岁入行，和父亲一起捆烟叶、送烟草，后来在一家小厂做茄套和包装；他在桑坦德工业大学读企业管理——一家报纸说第七学期中断，另一家说已毕业；词条两者都写——并去古巴学习另一种做烟草的方法。他的品牌2000年先叫 Cigarros Chicamocha，取自附近的峡谷，2006年改为 Corona Real。

皮耶德奎斯塔自建镇起就在卷制，他说哥伦比亚95%的烟草产自这里——但那是 tabaco，每支几百比索、养活数千家庭的大众雪茄。Corona Real 做的是另一件事：puro，全手工，约八个人，烟叶九成来自哥伦比亚——希龙、塞皮塔、洛斯桑托斯台地、卡皮塔内霍、库库塔、马里亚山——加上他窖藏陈化的2005至2006年厄瓜多尔苏门答腊茄衣。三个本地品种：Costeña、Guane、Cubita。

他在哥伦比亚全国销售，却没能出口——2021年他说，每次尝试都被限制拦下；至于他的雪茄到过名人手里，那是他讲的轶事，图集不予转述。一份来自哥伦比亚西班牙语媒体的词条，写的是一家雪茄媒体从未写过的公司。',
        '[{"name":"Corona Real","color":"#8B6914","force":"Medium","wrapper":"厄瓜多尔苏门答腊或哥伦比亚","vitolas":[],"story":"公司的 puro，全手工，桑坦德烟叶配2005至2006年起陈化的厄瓜多尔苏门答腊茄衣。"}]',
        'Corona Real دار غابرييل بيكو غوتييريس في بييديكويستا، مدينة التبغ في سانتاندير جنوب بوكارامانغا. دخلها في الثانية عشرة، يربط الأوراق ويوزّع التبغ مع أبيه، ثمّ يعمل في مصنع صغير في الرابط والتعبئة؛ ودرس الإدارة في الجامعة الصناعية في سانتاندير — انقطعت في الفصل السابع بحسب صحيفة، وأُتمّت بحسب أخرى؛ تكتب البطاقة الاثنتين — وذهب إلى كوبا ليتعلّم صنع التبغ على نحو آخر. سُمّيت علامته أوّلًا Cigarros Chicamocha سنة 2000، على اسم الأخدود المجاور، ثمّ Corona Real سنة 2006.

تلفّ بييديكويستا منذ تأسيسها، ويقول إنّ 95 % من التبغ الكولومبي يُصنع فيها — لكنّه التبغ الشعبي، السيجار العامّ الذي يعيل آلاف الأسر ببضع مئات من البيزو للقطعة. تصنع Corona Real شيئًا آخر: سيجارًا فاخرًا، كلّه باليد، بنحو ثمانية أشخاص، على تبغ كولومبي بنسبة 90 % يأتي من خيرون وسيبيتا وميسا دي لوس سانتوس وكابيتانيخو وكوكوتا ومونتيس دي ماريا، وعلى أغلفة سومطرة من الإكوادور من 2005-2006 يحتفظ بها للتعتيق. ثلاثة أصناف محلية: Costeña وGuane وCubita.

يبيع في كولومبيا كلّها ولم ينجح في التصدير — كلّما حاول أوقفته القيود، كما قال سنة 2021؛ أمّا أنّ سيجاره وصل إلى مشاهير فحكاية يرويها ولا يعيدها الأطلس. بطاقة من الصحافة الكولومبية، بالإسبانية، لدار لم تكتبها صحافة السيجار قطّ.',
        '[{"name":"Corona Real","color":"#8B6914","force":"Medium","wrapper":"سومطرة من الإكوادور أو كولومبية","vitolas":[],"story":"سيجار الدار الفاخر، كلّه باليد، على تبغ سانتاندير وغلاف سومطرة من الإكوادور معتَّق منذ 2005-2006."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Colpuros ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Colpuros',
        'colombia',
        '5 août 2009 — Piedecuesta ; Yorgan Correa',
        'Fabrique propre — Avenida 7N 17A-51, Quinta Granada, Piedecuesta ; rouleuses formées par des Cubains et des Dominicains, effectif non publié',
        'vanguardia.com « Tras cuatro años, tabaco local vuelve a ser tipo exportación » (9 septembre 2018 : Colpuros, Yorgan Correa Rodríguez, place des puros premium en Allemagne après quatre ans sans export du secteur ; Belgique, Russie, Espagne, Suède visées ; Piedecuesta — 6 500 familles, 200 fabricants, 78 % de femmes, 40 % du produit municipal ; Mary Sequeda sur les semences) ; colpuros.com « Nosotros » (créée le 5 août 2009 ; Yorgan Correa Rodríguez, économiste, né le 10 septembre 1974 ; Laura Victoria Heredia Portillo, cofondatrice ; lignée Correa depuis Agustín Correa à Zapatoca, il y a cent cinquante ans, puis José Correa ; rouleuses formées par des Cubains et des Dominicains, toutes des femmes chefs de famille ; tabac de semence cubaine cultivé en Colombie, feuilles d''Équateur, du Nicaragua, du Honduras et de République dominicaine ; marques Don José Correa et Mosqueteros) ; amigosysocios.com — sources en espagnol, presse colombienne',
        'Colpuros — Compañía Colombiana de Puros — est née le 5 août 2009 à Piedecuesta, dans le Santander, et c''est la maison d''une lignée : Agustín Correa faisait du tabaco à Zapatoca il y a cent cinquante ans, son fils José Correa a amélioré la feuille et la vente, et le petit-fils, Yorgan Correa Rodríguez, économiste né en 1974, a voulu passer du tabaco populaire au puro d''exportation. Il a fondé la société avec Laura Victoria Heredia Portillo, qui tient l''administration et le personnel, et a baptisé sa ligne fine Don José Correa, du nom de son père ; Mosqueteros est la ligne de tabaco et de semi-fins.

L''atelier est dans le quartier de Quinta Granada. Les rouleuses, toutes des femmes chefs de famille, dit la maison, ont été formées par des Cubains et des Dominicains ; le tabac est de semence cubaine cultivée en Colombie, complété de feuilles d''Équateur, du Nicaragua, du Honduras et de République dominicaine. L''effectif n''est pas publié.

En septembre 2018, le journal de Bucaramanga écrivait que Colpuros venait de placer des puros premium en Allemagne, après quatre ans sans qu''aucune maison de Piedecuesta n''exporte — dans une ville où deux cents fabricants, 78 % de femmes, font vivre 6 500 familles avec le tabac, qui pèse 40 % du produit municipal. La Belgique, la Russie, l''Espagne et la Suède étaient visées ensuite ; la fiche ne sait pas ce qu''il en est advenu. Que la maison se dise seule certifiée à l''export est son affirmation ; l''atlas la lui laisse.',
        '[{"name":"Don José Correa","color":"#5C2E1E","force":"Medium-Full","wrapper":"Colombienne ou importée","vitolas":[],"story":"La ligne fine, au nom du père — tout à la main, semence cubaine cultivée en Colombie ; placée en Allemagne en 2018."},{"name":"Mosqueteros","color":"#A0522D","force":"Medium","wrapper":"Colombienne ou importée","vitolas":[],"story":"La ligne de tabaco et de semi-fins — le cigare populaire du Santander, hors du cœur de cet atlas."}]',
        'Colpuros — Compañía Colombiana de Puros — was born on 5 August 2009 in Piedecuesta, Santander, and it is the house of a lineage: Agustín Correa made tabaco in Zapatoca a hundred and fifty years ago, his son José Correa improved the leaf and the selling, and the grandson, Yorgan Correa Rodríguez, an economist born in 1974, wanted to move from popular tabaco to export puro. He founded the company with Laura Victoria Heredia Portillo, who runs administration and staff, and named his fine line Don José Correa, after his father; Mosqueteros is the line of tabaco and semi-fine.

The workshop is in the Quinta Granada neighbourhood. The rollers, all women heads of household, says the house, were trained by Cubans and Dominicans; the tobacco is Cuban seed grown in Colombia, completed with leaf from Ecuador, Nicaragua, Honduras and the Dominican Republic. The headcount is not published.

In September 2018 the Bucaramanga paper wrote that Colpuros had just placed premium puros in Germany, after four years in which no Piedecuesta house had exported — in a town where two hundred makers, 78% women, feed 6,500 families with tobacco, which weighs 40% of the municipal product. Belgium, Russia, Spain and Sweden were targeted next; the entry does not know what became of it. That the house calls itself the only one certified for export is its own claim; the atlas leaves it to it.',
        '[{"name":"Don José Correa","color":"#5C2E1E","force":"Medium-Full","wrapper":"Colombian or imported","vitolas":[],"story":"The fine line, named after the father — all by hand, Cuban seed grown in Colombia; placed in Germany in 2018."},{"name":"Mosqueteros","color":"#A0522D","force":"Medium","wrapper":"Colombian or imported","vitolas":[],"story":"The line of tabaco and semi-fine — Santander''s popular cigar, outside the heart of this atlas."}]',
        'Colpuros — Compañía Colombiana de Puros — nació el 5 de agosto de 2009 en Piedecuesta, Santander, y es la casa de un linaje: Agustín Correa hacía tabaco en Zapatoca hace ciento cincuenta años, su hijo José Correa mejoró la hoja y la venta, y el nieto, Yorgan Correa Rodríguez, economista nacido en 1974, quiso pasar del tabaco popular al puro de exportación. Fundó la sociedad con Laura Victoria Heredia Portillo, que lleva la administración y el personal, y bautizó su línea fina Don José Correa, por su padre; Mosqueteros es la línea de tabaco y semifinos.

El taller está en el barrio de Quinta Granada. Las torcedoras, todas mujeres cabeza de familia, dice la casa, fueron formadas por cubanos y dominicanos; el tabaco es de semilla cubana cultivada en Colombia, completado con hojas de Ecuador, Nicaragua, Honduras y República Dominicana. La plantilla no se publica.

En septiembre de 2018 el diario de Bucaramanga escribía que Colpuros acababa de colocar puros premium en Alemania, tras cuatro años sin que ninguna casa de Piedecuesta exportara — en una ciudad donde doscientos fabricantes, 78 % mujeres, sostienen a 6 500 familias con el tabaco, que pesa el 40 % del producto municipal. Bélgica, Rusia, España y Suecia venían después; la ficha no sabe qué fue de ello. Que la casa se diga la única certificada para exportar es afirmación suya; el atlas se la deja.',
        '[{"name":"Don José Correa","color":"#5C2E1E","force":"Medium-Full","wrapper":"Colombiana o importada","vitolas":[],"story":"La línea fina, con el nombre del padre — todo a mano, semilla cubana cultivada en Colombia; colocada en Alemania en 2018."},{"name":"Mosqueteros","color":"#A0522D","force":"Medium","wrapper":"Colombiana o importada","vitolas":[],"story":"La línea de tabaco y semifinos — el cigarro popular de Santander, fuera del corazón de este atlas."}]',
        'Colpuros — Compañía Colombiana de Puros — entstand am 5. August 2009 in Piedecuesta, Santander, und ist das Haus einer Linie: Agustín Correa machte vor hundertfünfzig Jahren tabaco in Zapatoca, sein Sohn José Correa verbesserte Blatt und Verkauf, und der Enkel, Yorgan Correa Rodríguez, Ökonom, Jahrgang 1974, wollte vom Volks-tabaco zum Export-Puro übergehen. Er gründete die Firma mit Laura Victoria Heredia Portillo, die Verwaltung und Personal führt, und nannte seine feine Linie Don José Correa, nach seinem Vater; Mosqueteros ist die Linie für tabaco und Halbfeines.

Die Werkstatt liegt im Viertel Quinta Granada. Die Rollerinnen, alle Frauen und Familienvorstände, sagt das Haus, wurden von Kubanern und Dominikanern ausgebildet; der Tabak ist kubanisches Saatgut, in Kolumbien angebaut, ergänzt um Blätter aus Ecuador, Nicaragua, Honduras und der Dominikanischen Republik. Die Belegschaft wird nicht veröffentlicht.

Im September 2018 schrieb die Zeitung von Bucaramanga, Colpuros habe gerade Premium-Puros in Deutschland platziert, nach vier Jahren, in denen kein Haus aus Piedecuesta exportiert hatte — in einer Stadt, in der zweihundert Hersteller, 78 % Frauen, 6 500 Familien vom Tabak ernähren, der 40 % des Gemeindeprodukts ausmacht. Belgien, Russland, Spanien und Schweden waren als Nächstes im Visier; der Eintrag weiß nicht, was daraus wurde. Dass das Haus sich als einziges für den Export zertifiziert nennt, ist seine eigene Behauptung; der Atlas überlässt sie ihm.',
        '[{"name":"Don José Correa","color":"#5C2E1E","force":"Medium-Full","wrapper":"Kolumbianisch oder importiert","vitolas":[],"story":"Die feine Linie, nach dem Vater benannt — ganz von Hand, kubanisches Saatgut aus Kolumbien; 2018 in Deutschland platziert."},{"name":"Mosqueteros","color":"#A0522D","force":"Medium","wrapper":"Kolumbianisch oder importiert","vitolas":[],"story":"Die Linie für tabaco und Halbfeines — Santanders Volkszigarre, außerhalb des Kerns dieses Atlas."}]',
        'Colpuros——哥伦比亚雪茄公司——2009年8月5日诞生于桑坦德省皮耶德奎斯塔，是一个世系的公司：一百五十年前阿古斯丁·科雷亚在萨帕托卡做 tabaco，其子何塞·科雷亚改良了烟叶和销售，而孙子约尔甘·科雷亚·罗德里格斯，1974年出生的经济学家，想从大众 tabaco 转向出口 puro。他与劳拉·维多利亚·埃雷迪亚·波蒂略共同创立公司，后者负责行政和人事；他以父亲之名把精品线命名为 Don José Correa；Mosqueteros 是 tabaco 和半精品线。

作坊在金塔格拉纳达街区。公司说，卷工全是女性户主，由古巴人和多米尼加人培训；烟叶是在哥伦比亚种植的古巴种，辅以厄瓜多尔、尼加拉瓜、洪都拉斯和多米尼加的烟叶。员工人数未公布。

2018年9月，布卡拉曼加的报纸写道，Colpuros 刚把高档 puro 送进德国，此前四年皮耶德奎斯塔没有任何一家出口——这座城里两百家制造者、78%为女性，靠烟草养活6500个家庭，烟草占市产值40%。接下来瞄准比利时、俄罗斯、西班牙和瑞典；词条不知道后来如何。公司自称是唯一持有出口认证的企业，那是它自己的说法；图集留给它。',
        '[{"name":"Don José Correa","color":"#5C2E1E","force":"Medium-Full","wrapper":"哥伦比亚或进口","vitolas":[],"story":"以父亲命名的精品线——全手工，哥伦比亚种植的古巴种；2018年进入德国。"},{"name":"Mosqueteros","color":"#A0522D","force":"Medium","wrapper":"哥伦比亚或进口","vitolas":[],"story":"tabaco 和半精品线——桑坦德的大众雪茄，不在本图集的核心之内。"}]',
        'Colpuros — الشركة الكولومبية للسيجار الفاخر — وُلدت في 5 أغسطس 2009 في بييديكويستا بسانتاندير، وهي دار سلالة: كان أغوستين كوريا يصنع التبغ الشعبي في زاباتوكا قبل مئة وخمسين سنة، وحسّن ابنه خوسيه كوريا الورقة والبيع، وأراد الحفيد يورغان كوريا رودريغيس، الاقتصادي المولود سنة 1974، الانتقال من التبغ الشعبي إلى سيجار التصدير الفاخر. أسّس الشركة مع لاورا فيكتوريا إيريديا بورتيّو، التي تتولّى الإدارة والموظّفين، وسمّى خطّه الرفيع Don José Correa على اسم أبيه؛ أمّا Mosqueteros فخطّ التبغ الشعبي ونصف الرفيع.

الورشة في حيّ كينتا غرانادا. اللفّافات، وكلّهنّ نساء يعُلن أسرهنّ كما تقول الدار، درّبهنّ كوبيون ودومينيكيون؛ والتبغ من بذور كوبية تُزرع في كولومبيا، تكمّله أوراق من الإكوادور ونيكاراغوا وهندوراس وجمهورية الدومينيكان. وعدد العاملين غير منشور.

في سبتمبر 2018 كتبت صحيفة بوكارامانغا أنّ Colpuros وضعت للتوّ سيجارًا فاخرًا في ألمانيا، بعد أربع سنوات لم تصدّر فيها أيّ دار من بييديكويستا — في مدينة يعيل فيها مئتا صانع، 78 % منهم نساء، 6500 أسرة بالتبغ الذي يزن 40 % من ناتج البلدية. وكانت بلجيكا وروسيا وإسبانيا والسويد هي التالية؛ ولا تعرف البطاقة ما آل إليه الأمر. وأمّا قول الدار إنّها الوحيدة المعتمدة للتصدير فادّعاؤها هي؛ ويتركه الأطلس لها.',
        '[{"name":"Don José Correa","color":"#5C2E1E","force":"Medium-Full","wrapper":"كولومبية أو مستوردة","vitolas":[],"story":"الخطّ الرفيع باسم الأب — كلّه باليد، بذور كوبية تُزرع في كولومبيا؛ وُضع في ألمانيا سنة 2018."},{"name":"Mosqueteros","color":"#A0522D","force":"Medium","wrapper":"كولومبية أو مستوردة","vitolas":[],"story":"خطّ التبغ الشعبي ونصف الرفيع — سيجار سانتاندير العامّ، خارج قلب هذا الأطلس."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Aruhiba ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Aruhiba',
        'aruba',
        '2005 — Noord (Aruba) ; Benjamin Petrocchi',
        'Atelier propre — près du moulin De Oude Molen, Noord ; deux femmes trient et roulent l''après-midi, environ quarante cigares par heure, dit un guide néerlandais',
        'arubaconventionbureau.com, office du tourisme (Benjamin Petrocchi roule ses cigares en tabac cultivé sur place ; pesticide naturel au margousier ; boutique près du moulin hollandais de Palm Beach ; classiques et vanillés) ; inyourpocket.com (depuis 2005 ; L.G. Smith Blvd 330 ; cours de roulage) ; beautiful-aruba.nl, guide en néerlandais (deux emplacements — De Oude Molen et un centre commercial d''Oranjestad ; J.E. Irausquin Blvd 330 ; deux femmes trient le matin, roulage l''après-midi, environ quarante cigares par heure ; feuilles claires et sombres ; fils de cultivateurs de haricots) ; leafenthusiast.com (8 septembre 2014 : petit corona 5,5 × 44 ; le site de la maison ne disait ni les origines ni les formats) ; tripadvisor.com (« 21 ans » en 2026) — l''ancien domaine de la maison sert aujourd''hui une boutique en Ukraine sans rapport, non cité',
        'Aruhiba est le cigare d''Aruba, et il n''y en a pas d''autre : Benjamin Petrocchi, fils d''une famille qui cultivait des haricots, a mis sur la même terre du tabac et s''est mis à le rouler. Depuis 2005, dit un annuaire de voyage, et les visiteurs de 2026 comptent vingt et un ans ; ni la presse du cigare ni la presse locale n''ont daté la chose autrement. L''atelier est à Noord, près du moulin hollandais de Palm Beach, à hauteur des hôtels ; une seconde boutique est à Oranjestad.

Un guide néerlandais décrit l''après-midi : deux femmes qui ont trié les feuilles le matin roulent, environ quarante cigares par heure, des feuilles claires et des sombres ; l''office du tourisme ajoute que les plants sont protégés avec un extrait de margousier plutôt qu''un pesticide de synthèse. Cultivé, séché et roulé sur une île aride de cent quatre-vingts kilomètres carrés, du cactus et du vent — l''atlas ne connaît pas d''autre cigare fait de bout en bout sur une île aussi petite, et ne sait pas si la cape est d''ailleurs : la maison ne l''a jamais écrit, notait déjà un dégustateur en 2014.

C''est une fiche de sources touristiques, en anglais et en néerlandais, et elle le dit ; l''ancien domaine de la maison sert aujourd''hui une boutique en Ukraine sans rapport avec elle, et l''atlas ne le cite pas. Aruba entre comme lieu de roulage et de culture, à l''échelle d''une boutique.',
        '[{"name":"Aruhiba Classic","color":"#6E8B3D","force":"Mild","wrapper":"Arubaine — cultivée sur l’île","vitolas":[],"story":"Le cigare de l''île, feuilles claires ou sombres, roulé l''après-midi près du moulin — petit corona de 5,5 × 44 vu en 2014."}]',
        'Aruhiba is Aruba''s cigar, and there is no other: Benjamin Petrocchi, the son of a family that grew beans, put tobacco on the same land and began rolling it. Since 2005, says a travel directory, and visitors in 2026 count twenty-one years; neither the cigar press nor the local press has dated it otherwise. The workshop is in Noord, near the Dutch windmill of Palm Beach, level with the hotels; a second shop is in Oranjestad.

A Dutch guide describes the afternoon: two women who sorted the leaves in the morning roll, about forty cigars an hour, light leaves and dark; the tourism office adds that the plants are protected with a neem extract rather than a synthetic pesticide. Grown, cured and rolled on an arid island of a hundred and eighty square kilometres, cactus and wind — this atlas knows no other cigar made end to end on so small an island, and does not know whether the wrapper is from elsewhere: the house has never written it, a taster already noted in 2014.

It is an entry from tourism sources, in English and Dutch, and it says so; the house''s former domain now serves a shop in Ukraine unrelated to it, and the atlas does not cite it. Aruba enters as a rolling and growing place, on the scale of a shop.',
        '[{"name":"Aruhiba Classic","color":"#6E8B3D","force":"Mild","wrapper":"Aruban — grown on the island","vitolas":[],"story":"The island''s cigar, light or dark leaves, rolled in the afternoon near the windmill — a 5.5 × 44 petit corona seen in 2014."}]',
        'Aruhiba es el puro de Aruba, y no hay otro: Benjamin Petrocchi, hijo de una familia que cultivaba frijoles, puso tabaco en la misma tierra y se puso a liarlo. Desde 2005, dice un directorio de viajes, y los visitantes de 2026 cuentan veintiún años; ni la prensa del puro ni la prensa local lo han fechado de otro modo. El taller está en Noord, junto al molino holandés de Palm Beach, a la altura de los hoteles; una segunda tienda está en Oranjestad.

Una guía neerlandesa describe la tarde: dos mujeres que clasificaron las hojas por la mañana lían, unos cuarenta puros por hora, hojas claras y oscuras; la oficina de turismo añade que las plantas se protegen con un extracto de nim en lugar de un pesticida sintético. Cultivado, curado y liado en una isla árida de ciento ochenta kilómetros cuadrados, cactus y viento — este atlas no conoce otro puro hecho de principio a fin en una isla tan pequeña, y no sabe si la capa es de otra parte: la casa nunca lo escribió, ya anotaba un catador en 2014.

Es una ficha de fuentes turísticas, en inglés y en neerlandés, y lo dice; el antiguo dominio de la casa sirve hoy a una tienda en Ucrania sin relación con ella, y el atlas no lo cita. Aruba entra como lugar de liado y de cultivo, a la escala de una tienda.',
        '[{"name":"Aruhiba Classic","color":"#6E8B3D","force":"Mild","wrapper":"Arubana — cultivada en la isla","vitolas":[],"story":"El puro de la isla, hojas claras u oscuras, liado por la tarde junto al molino — petit corona de 5,5 × 44 visto en 2014."}]',
        'Aruhiba ist die Zigarre Arubas, und es gibt keine andere: Benjamin Petrocchi, Sohn einer Familie, die Bohnen anbaute, setzte Tabak auf dasselbe Land und begann, ihn zu rollen. Seit 2005, sagt ein Reiseverzeichnis, und Besucher zählen 2026 einundzwanzig Jahre; weder die Zigarrenpresse noch die Lokalpresse hat es anders datiert. Die Werkstatt liegt in Noord, bei der holländischen Windmühle von Palm Beach, auf Höhe der Hotels; ein zweiter Laden ist in Oranjestad.

Ein niederländischer Führer beschreibt den Nachmittag: Zwei Frauen, die morgens die Blätter sortiert haben, rollen, etwa vierzig Zigarren in der Stunde, helle Blätter und dunkle; das Fremdenverkehrsamt fügt hinzu, dass die Pflanzen mit einem Niem-Extrakt statt eines synthetischen Pestizids geschützt werden. Angebaut, getrocknet und gerollt auf einer kargen Insel von hundertachtzig Quadratkilometern, Kakteen und Wind — dieser Atlas kennt keine andere Zigarre, die von Anfang bis Ende auf einer so kleinen Insel entsteht, und weiß nicht, ob das Deckblatt von anderswo kommt: Das Haus hat es nie geschrieben, wie ein Verkoster schon 2014 vermerkte.

Es ist ein Eintrag aus touristischen Quellen, auf Englisch und Niederländisch, und er sagt es; die frühere Domain des Hauses bedient heute einen Laden in der Ukraine ohne Bezug zu ihm, und der Atlas zitiert sie nicht. Aruba tritt als Roll- und Anbauort ein, im Maßstab eines Ladens.',
        '[{"name":"Aruhiba Classic","color":"#6E8B3D","force":"Mild","wrapper":"Arubanisch — auf der Insel angebaut","vitolas":[],"story":"Die Zigarre der Insel, helle oder dunkle Blätter, nachmittags bei der Mühle gerollt — ein Petit Corona 5,5 × 44, 2014 gesehen."}]',
        'Aruhiba 是阿鲁巴的雪茄，别无其他：本杰明·佩特罗基出身种豆人家，在同一片地上种下烟草，并开始卷制。一份旅行名录说自2005年起，2026年的游客数着二十一年；雪茄媒体和本地媒体都没有给出别的日期。作坊在诺德，棕榈滩荷兰风车旁，与酒店平齐；奥拉涅斯塔德还有第二家店。

一本荷兰指南描述了下午的情形：两位早上分拣烟叶的女性在卷制，每小时约四十支，浅色叶和深色叶；旅游局补充说，烟株用印楝提取物而非合成农药保护。在一座一百八十平方公里、仙人掌和风的干旱岛上种植、晾制、卷制——本图集不知道还有哪支雪茄在这么小的岛上从头到尾完成，也不知道茄衣是否来自别处：公司从未写过，2014年一位品鉴者就已指出。

这是一份来自英语和荷兰语旅游资料的词条，并如实说明；公司过去的域名如今是一家与它无关的乌克兰店铺，图集不引用它。阿鲁巴以卷制与种植之地进入图集，规模只是一家店。',
        '[{"name":"Aruhiba Classic","color":"#6E8B3D","force":"Mild","wrapper":"阿鲁巴——岛上种植","vitolas":[],"story":"岛上的雪茄，浅叶或深叶，下午在风车旁卷制——2014年见到的5.5×44小皇冠。"}]',
        'Aruhiba سيجار أروبا، ولا سيجار غيره: بنيامين بتروكي، ابن عائلة كانت تزرع الفاصولياء، وضع التبغ في الأرض نفسها وشرع يلفّه. منذ 2005، يقول دليل سفر، ويعدّ زوّار 2026 إحدى وعشرين سنة؛ ولم تؤرّخه صحافة السيجار ولا الصحافة المحلية على نحو آخر. الورشة في نورد، قرب الطاحونة الهولندية في بالم بيتش، بمحاذاة الفنادق؛ ومتجر ثانٍ في أورانييستاد.

يصف دليل هولندي فترة ما بعد الظهر: امرأتان فرزتا الأوراق في الصباح تلفّان، نحو أربعين سيجارًا في الساعة، أوراقًا فاتحة وداكنة؛ ويضيف مكتب السياحة أنّ النبتات تُحمى بمستخلص النيم بدل مبيد صناعي. مزروع ومجفّف وملفوف في جزيرة قاحلة مساحتها مئة وثمانون كيلومترًا مربّعًا، صبّار وريح — لا يعرف هذا الأطلس سيجارًا آخر يُصنع من أوّله إلى آخره في جزيرة بهذا الصغر، ولا يعرف إن كان الغلاف من مكان آخر: لم تكتبه الدار قطّ، كما لاحظ متذوّق منذ 2014.

هذه بطاقة من مصادر سياحية، بالإنجليزية والهولندية، وتقول ذلك؛ أمّا نطاق الدار القديم فيخدم اليوم متجرًا في أوكرانيا لا صلة له بها، ولا يستشهد به الأطلس. تدخل أروبا مكانَ لفّ وزراعة، على مقياس متجر.',
        '[{"name":"Aruhiba Classic","color":"#6E8B3D","force":"Mild","wrapper":"أروبية — تُزرع في الجزيرة","vitolas":[],"story":"سيجار الجزيرة، أوراق فاتحة أو داكنة، يُلفّ بعد الظهر قرب الطاحونة — بيتي كورونا 5.5 × 44 شوهد سنة 2014."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);


INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'producer_countries', p.`id`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'region' THEN p.`region` WHEN 'production' THEN p.`production`
                         WHEN 'rev_detail' THEN p.`rev_detail` ELSE p.`notes` END), 'machine', NOW()
  FROM `producer_countries` p
  JOIN (SELECT 'region' champ UNION ALL SELECT 'production' UNION ALL SELECT 'rev_detail' UNION ALL SELECT 'notes') c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE p.`id` IN ('zimbabwe','southafrica','peru','colombia','aruba')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `maj` = NOW();

INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'producer_geo', g.`country_id`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'currency' THEN g.`currency` WHEN 'language' THEN g.`language` ELSE g.`independent` END), 'machine', NOW()
  FROM `producer_geo` g
  JOIN (SELECT 'currency' champ UNION ALL SELECT 'language' UNION ALL SELECT 'independent') c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE g.`country_id` IN ('zimbabwe','southafrica','peru','colombia','aruba')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `maj` = NOW();

INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'production_zones', z.`id`, 'note', l.lang, SHA1(z.`note`), 'machine', NOW()
  FROM `production_zones` z
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE z.`id` IN (51, 52)
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `maj` = NOW();

INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` ELSE b.`gamme` END), 'machine', NOW()
  FROM `brands` b
  JOIN (SELECT 'history' champ UNION ALL SELECT 'gamme') c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE b.`name` IN ('Mosi Oa Tunya','Santa Bras','Tabacalera del Oriente','Corona Real','Colpuros','Aruhiba')
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `maj` = NOW();

DELETE FROM `moderation_log` WHERE `acteur_nom` = 'migration 223';
