  (`acteur_id`, `acteur_nom`, `portee`, `action`, `cible_type`, `cible_id`, `detail`)
VALUES
  (NULL,'migration 223','systeme','cinq_pays_de_roulage_afrique_ameriques','pays',0,
   'Zimbabwe (Harare), Afrique du Sud (George), Perou (Tarapoto), Colombie (Piedecuesta), Aruba (Noord) : cinq pays qui roulent a la main sans presse du cigare. Perou et Colombie entrent avec une zone chacun ; les trois autres declarent leurs trous'),
  (NULL,'migration 223','systeme','dates_divergentes_ecrites','marque',0,
   'Mosi Oa Tunya : mars, mai ou juillet 2020 selon le journal. Tabacalera del Oriente : milieu du XXe, 1997 ou vers 2000. Gabriel Pico : etudes achevees ou non. Chaque fiche ecrit les versions au lieu d en choisir une'),
  (NULL,'migration 223','systeme','sources_locales_declarees','marque',0,
   'Presse anglophone du Zimbabwe et d Afrique du Sud, presse peruvienne et colombienne en espagnol, sources touristiques en anglais et neerlandais pour Aruba — dites dans chaque fiche. L ancien domaine d Aruhiba sert une boutique ukrainienne : non cite');

SELECT
  (SELECT COUNT(*) FROM `producer_countries` WHERE `id` IN ('zimbabwe','southafrica','peru','colombia','aruba')) = 5 AS cinq_pays,
  (SELECT COUNT(*) FROM `producer_geo` WHERE `country_id` IN ('zimbabwe','southafrica','peru','colombia','aruba')) = 5 AS cinq_geo,
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('Mosi Oa Tunya','Santa Bras','Tabacalera del Oriente','Corona Real','Colpuros','Aruhiba')) = 6 AS six_fiches,
  (SELECT CHAR_LENGTH(`flag`) FROM `producer_countries` WHERE `id` = 'zimbabwe') = 2 AS drapeau_entier,
  (SELECT COUNT(*) FROM `production_zones` WHERE `id` IN (51, 52)) = 2 AS deux_zones,
  (SELECT JSON_LENGTH(`brands`) FROM `producer_countries` WHERE `id` = 'colombia') = 2 AS colombie_deux,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 223') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
SELECT COUNT(*) AS pays_producteurs FROM `producer_countries`;
